def make_hobbies_words():
    words = []
    subs = ["sports_games", "music_instruments", "art_creativity", "outdoor_activities", "gaming_entertainment"]
    for i, w in enumerate(hobbies_data):
        sub = subs[i // 50]
        words.append((w[0], w[1], w[2], f"[{w[0].lower()}]", w[3], w[4], w[5], w[6], "hobbies", sub, w[7]))
    return words

